static void mtk_hdmi_register_audio_driver ( struct device * dev ) { struct hdmi_codec_pdata codec_data = { . ops = & mtk_hdmi_audio_codec_ops . max_i2s_channels = 2 . i2s = 1 } ; struct platform_device * pdev ; pdev = platform_device_register_data ( dev , HDMI_CODEC_DRV_NAME , PLATFORM_DEVID_AUTO , & codec_data , sizeof ( codec_data ) ) ; DRM_INFO ( "%s driver bound to HDMI\n" , HDMI_CODEC_DRV_NAME ) ; } 